<script setup lang="ts">
import { computed } from 'vue';
import { route as routeSource,go,setQuery,back } from '../workbench/navigation';
import { learningSpaces } from '../workbench/learning-space-mock';
import { observationSections,observationData,observationMetrics,dateMatches,type ObservationLink } from '../workbench/runtime-observation';
import WorkbenchDialog from './WorkbenchDialog.vue';
import PagingBar from './PagingBar.vue';
const route=routeSource,location=window.location;
const section=computed(()=>observationSections.find(s=>s.id===route.tab)||observationSections[0]);
const invalidSection=computed(()=>!!route.tab&&!observationSections.some(s=>s.id===route.tab));
const chosen=computed(()=>learningSpaces.find(s=>s.id===route.scope));
const invalidScope=computed(()=>!!route.scope&&!chosen.value);
const students=[...new Map(learningSpaces.map(s=>[s.studentId,s.studentName])).entries()];
const dateError=computed(()=>route.range==='custom'&&route.since&&route.until&&route.since>route.until);
const data=computed(()=>observationData(section.value.id,route.scope));
const period=computed(()=>data.value.records.filter(r=>r.current||dateMatches(r.at,route.range,route.since,route.until)));
const metrics=computed(()=>observationMetrics(section.value.id,data.value,period.value));
const attention=computed(()=>period.value.filter(r=>r.attention));
const catalog=computed(()=>route.result==='catalog');
const entries=computed(()=>catalog.value?data.value.catalog:period.value);
const kinds=computed(()=>[...new Set(entries.value.map(r=>r.kind))]);
const rows=computed(()=>entries.value.filter(r=>(!route.filter||r.kind===route.filter)&&(!route.review||r.attention)&&`${r.id} ${r.kind} ${r.title} ${r.summary} ${r.fields.map(f=>f.join(' ')).join(' ')} ${r.links.map(l=>Object.values(l.values).join(' ')).join(' ')} ${r.scopeIds.map(spaceName).join(' ')}`.toLowerCase().includes(route.q.trim().toLowerCase())).sort((a,b)=>Number(b.attention)-Number(a.attention)||b.at.localeCompare(a.at)||a.id.localeCompare(b.id)));
const page=computed(()=>Math.min(route.p,Math.max(1,Math.ceil(rows.value.length/10))));
const selected=computed(()=>[...data.value.records,...data.value.catalog].find(r=>r.id===route.id));
function spaceName(id:string){const s=learningSpaces.find(s=>s.id===id);return s?s.studentName+' · '+s.name:id;}
function reset(){setQuery({scope:'',range:'all',since:'',until:'',filter:'',review:'',q:'',id:'',p:1});}
function openLink(target:ObservationLink){go(target.page,{...target.values,returnTo:location.hash});}
function selectView(value:string){setQuery({result:value,filter:'',review:'',q:'',id:'',p:1});}
</script>
<template><div class="runtime-observation">
  <div class="observation-body">
    <button v-if="route.returnTo.startsWith('#/dashboard')" class="text-link" @click="back()">← 返回运行总览</button>
    <header class="page-header"><div><h2>{{section.title}}</h2><p class="page-desc">{{section.description}}</p></div><span class="badge">Mock · 人工示例</span></header>
    <div class="scope-toolbar"><label>观测范围<select aria-label="观测范围" :value="route.scope" @change="setQuery({scope:($event.target as HTMLSelectElement).value,id:'',q:'',p:1})"><option value="">全部学习空间（记录聚合）</option><option v-if="invalidScope" :value="route.scope">{{route.scope}} · 范围不存在</option><optgroup v-for="[id,name] in students" :key="id" :label="name"><option v-for="s in learningSpaces.filter(s=>s.studentId===id)" :key="s.id" :value="s.id">{{s.name}} · {{s.id}}</option></optgroup></select></label><label>变化时间<select aria-label="变化时间" :value="route.range||'all'" @change="setQuery({range:($event.target as HTMLSelectElement).value,id:'',p:1})"><option value="all">全部记录</option><option value="today">今天</option><option value="7days">近 7 天</option><option value="30days">近 30 天</option><option value="custom">自定义日期</option></select></label><template v-if="route.range==='custom'"><label>开始日期<input type="date" :value="route.since" @input="setQuery({since:($event.target as HTMLInputElement).value,id:'',p:1})"/></label><label>结束日期<input type="date" :value="route.until" @input="setQuery({until:($event.target as HTMLInputElement).value,id:'',p:1})"/></label></template><button class="btn" @click="reset">重置筛选</button></div>
    <p v-if="chosen" class="scope-context">{{chosen.studentName}} · {{chosen.name}} · <span>{{chosen.id}}</span><button class="text-link" @click="go('learning-spaces',{id:chosen.id,returnTo:location.hash})">查看学习空间 →</button><button class="text-link" @click="go('students',{id:chosen.studentId,scope:chosen.id,returnTo:location.hash})">学生状态 →</button></p>
    <section v-if="invalidScope||invalidSection||dateError" class="panel"><p role="alert">{{invalidScope?'所选学习空间不存在，未扩大为全部学生。':invalidSection?'观测分区不存在，请从左侧重新选择。':'开始日期不能晚于结束日期。'}}</p></section>
    <template v-else>
      <p class="scope-note">“期间”按本机自然日筛选；“当前”保留最新已记录状态，不随日期回退。搜索与类型筛选只影响下方记录列表。</p>
      <section class="observation-metrics" aria-label="观测摘要"><div v-for="m in metrics" :key="m.label" class="metric-card"><span>{{m.label}}</span><strong>{{m.value}}</strong><small>{{m.note}}</small></div></section>
      <p v-if="section.id==='Reasoning'" class="callout reasoning-boundary">此处从交互审查的预写脚本汇总示例步骤。候选拒绝、重试与最终提交分别记录；不代表真实调用数量、准确率或性能。</p>
      <p v-if="section.id==='Interaction'" class="callout">以下状态快照只描述已记录轮次的上下文。当前是否仍在活动、检测或等待中尚未记录，不从最后一次处理完成推断。</p>
      <p v-if="section.id==='Evolution'" class="callout">采用差异来自当前目录与空间快照比较；是否需要更新尚待人工判断。领域内容尚无逐次修改日志时，只展示当前差异。</p>
      <section class="attention-panel"><div class="section-heading"><h3>{{section.id==='Reasoning'?'拒绝与失败记录':'待核对与证据缺口'}} <span>{{attention.length}}</span></h3><button v-if="attention.length>3" class="text-link" @click="setQuery({result:'',review:'attention',filter:'',q:'',p:1})">查看全部 →</button></div><div v-for="r in attention.slice(0,3)" :key="r.id" class="attention-row"><div><button class="text-link attention-title" @click="setQuery({id:r.id})">{{r.title}}</button><p>{{r.summary}}</p><small>{{r.scopeIds.map(spaceName).join('；')||'共享定义'}} · {{r.source}}</small></div><span class="badge amber">{{r.status}}</span></div><p v-if="!attention.length" class="empty">{{section.id==='Reasoning'?'所选期间暂无已记录的拒绝或失败。':'此范围暂无已记录的待核对项。未记录不等于系统已被证明没有问题。'}}</p></section>
      <div class="records-heading"><h3>{{catalog?'对象与引用':'运行记录与变化'}}</h3><button v-if="data.catalog.length" class="text-link" @click="selectView(catalog?'':'catalog')">{{catalog?'返回运行记录 →':'按对象查阅依据 →'}}</button></div>
      <p v-if="catalog" class="muted">对象视图用于核对引用与已采用内容；当前定义和空间采用快照分别查看，不在这里修改。</p>
      <div class="toolbar record-filters"><label class="search-label">搜索记录<input aria-label="搜索观测记录" type="search" :value="route.q" placeholder="对象、活动、学生或内容" @input="setQuery({q:($event.target as HTMLInputElement).value,p:1})"/></label><label>记录类型<select aria-label="记录类型" :value="route.filter" @change="setQuery({filter:($event.target as HTMLSelectElement).value,p:1})"><option value="">全部类型</option><option v-if="route.filter&&!kinds.includes(route.filter)" :value="route.filter">{{route.filter}}（本范围暂无）</option><option v-for="kind in kinds" :key="kind" :value="kind">{{kind}}</option></select></label><label v-if="!catalog" class="check-label"><input type="checkbox" :checked="!!route.review" @change="setQuery({review:($event.target as HTMLInputElement).checked?'attention':'',p:1})"/>{{section.id==='Reasoning'?'只看拒绝或失败':'只看待核对'}}</label><span class="muted">{{rows.length}} 条</span></div>
      <section class="table-card observation-records"><table class="data-table"><thead><tr><th>记录 / 对象</th><th>状态与变化</th><th>范围</th><th>记录时间</th><th></th></tr></thead><tbody><tr v-for="r in rows.slice((page-1)*10,page*10)" :key="r.id"><td><button class="text-link record-title" @click="setQuery({id:r.id})">{{r.title}}</button><small>{{r.kind}}</small></td><td><span class="badge" :class="{amber:r.attention}">{{r.status}}</span><p class="record-summary">{{r.summary}}</p></td><td><span v-if="!r.scopeIds.length" class="muted">共享定义 · 本范围暂无采用</span><span v-for="id in r.scopeIds" :key="id" class="scope-label">{{spaceName(id)}}</span></td><td>{{r.current?'当前快照':r.at||'未记录'}}<small v-if="r.current">不按变化日期过滤</small></td><td><button class="text-link" :aria-label="'查看依据 '+r.id" @click="setQuery({id:r.id})">查看依据 →</button></td></tr></tbody></table><p v-if="!rows.length" class="empty">当前范围和筛选下没有记录。未检测、无日志或暂无活动，都不能直接解释为学生未掌握或系统失败。</p></section>
      <PagingBar v-if="rows.length>10" :total="rows.length" :page="page"/>
      <details class="observation-boundaries"><summary>数据口径与历史示例</summary><p>当前页面共用领域、教材、目标、Claim、学习空间及交互审查中的 mock 数据。个人认识按学习空间隔离；聚合仅汇总记录，不合并能力。判断与待核对项来自既有示例及引用检查，不运行自动诊断。</p><p>活动步骤的日期沿用所属活动日期，耗时和模型输入输出为预写示例。当前采用差异不等于需要更新；未知的操作者、时间和中间版本保持未记录。</p><button class="text-link" @click="go('objects',{source:'legacy'})">查看旧版历史观测 →</button></details>
      <WorkbenchDialog v-if="route.id" :key="route.id" :title="selected?selected.kind+' · '+selected.title:'未找到该观测记录'" wide @close="setQuery({id:''})">
        <template v-if="selected"><div class="detail-context"><span class="badge" :class="{amber:selected.attention}">{{selected.status}}</span><span>{{selected.scopeIds.map(spaceName).join('；')||'共享定义'}}</span><span>{{selected.current?'当前快照':selected.at||'时间未记录'}}</span></div><p class="lead">{{selected.summary}}</p><p class="muted">{{selected.source}} · {{selected.id}}</p><dl class="field-list observation-fields"><template v-for="(field,i) in selected.fields" :key="i"><dt>{{field[0]}}</dt><dd>{{field[1]}}</dd></template></dl><details v-if="selected.raw" class="raw-observation"><summary>查看已记录原始内容</summary><pre>{{JSON.stringify(selected.raw,null,2)}}</pre></details><div class="dialog-footer"><p class="muted">本详情只读。前往管理页面会查看当前定义；历史活动和采用内容仍保留原快照。</p><div class="button-row"><button v-for="(target,i) in selected.links" :key="i" class="btn" @click="openLink(target)">{{target.label}}{{selected.links.filter(l=>l.label===target.label).length>1?' · '+(target.values.id||''):''}}</button></div></div></template>
        <p v-else class="callout amber">该记录不存在或不属于所选空间；不会用其他学生、活动或定义代替。</p>
      </WorkbenchDialog>
    </template>
  </div>
</div></template>
<style scoped>
.runtime-observation{display:flex;min-height:100%}.observation-body{flex:1;min-width:0;padding:24px;max-width:1600px}.page-header{margin-bottom:18px}.page-header>.badge{white-space:nowrap}.scope-toolbar{display:flex;align-items:end;gap:12px;flex-wrap:wrap}.scope-toolbar label{margin:0;flex:1;min-width:150px;max-width:310px}.scope-toolbar label:first-child{min-width:260px}.scope-context{display:flex;gap:10px;flex-wrap:wrap;font-size:13px;color:#56705f;margin:14px 0}.scope-context>span{color:#849087}.scope-context .text-link{margin-left:auto}.scope-note{font-size:12px;color:#758579;margin:14px 0}.observation-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-bottom:20px}.observation-metrics .metric-card{padding:14px}.observation-metrics .metric-card>span{font-size:12px}.observation-metrics strong{font-size:26px}.attention-panel{background:white;border:1px solid #e1e8ed;border-radius:9px;padding:16px 18px;margin:20px 0}.section-heading,.records-heading{display:flex;justify-content:space-between;align-items:center;gap:12px}.section-heading h3,.records-heading h3{font-size:15px;color:#355240;margin:0}.section-heading h3 span{font-size:12px;color:#7d8b81;margin-left:8px}.attention-row{display:flex;align-items:flex-start;justify-content:space-between;gap:18px;padding:14px 0;border-bottom:1px solid #ecf0ed}.attention-row:last-child{border-bottom:0;padding-bottom:0}.attention-title{font-size:14px;font-weight:600}.attention-row p{font-size:13px;color:#5b6f61;margin:6px 0}.attention-row small{font-size:11px;color:#87948b}.attention-row .badge{white-space:nowrap}.attention-panel .empty{padding:16px 0 0;font-size:12px;text-align:left}.records-heading{margin:24px 0 6px}.record-filters label{min-width:150px}.record-filters .check-label{white-space:nowrap;margin-bottom:7px}.record-filters>span{margin-left:auto;margin-bottom:9px}.observation-records{overflow-x:auto}.observation-records table{min-width:700px}.observation-records th:first-child{width:25%}.observation-records th:nth-child(2){width:37%}.observation-records th:nth-child(3){width:15%}.observation-records th:nth-child(4){width:125px}.observation-records th:last-child{width:92px}.record-title{font-size:13px;font-weight:600}.observation-records small{display:block;font-size:11px;color:#87938b;margin-top:5px}.record-summary{font-size:12px;color:#5f7568;margin:7px 0 0;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}.scope-label{display:block;font-size:12px;color:#617768;margin-bottom:5px}.observation-boundaries{font-size:12px;color:#7b8c80;margin:22px 0}.observation-boundaries p{margin:10px 0}.detail-context{display:flex;align-items:center;gap:12px;font-size:12px;color:#738677;flex-wrap:wrap}.observation-fields{margin:18px 0}.observation-fields dd{white-space:pre-wrap}.raw-observation{margin:18px 0}.dialog-footer .muted{margin:0 0 8px}@media(max-width:1200px){.observation-body{padding:18px}.observation-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.scope-toolbar label:first-child{min-width:220px}.page-header{flex-wrap:wrap}.attention-row{gap:12px}}@media(max-width:900px){.runtime-observation{display:block}.scope-toolbar label{max-width:none}.observation-body{padding:16px}}
</style>
